Find the value of $a$ so that the lines with the given equations are perpendicular. \begin{align*}
y &= 2x+13 \\
6y+ax &= 6.
\end{align*}

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>

using namespace std;

int main() {
    double a;

    // Equation of the first line
    double y1 = 2;
    double x1 = 13;

    // Equation of the second line
    double y2 = 6;
    double x2 = a;

    // Calculate the slope of the first line
    double slope1 = -y1 / x1;

    // Calculate the slope of the second line
    double slope2 = -y2 / x2;

    // Check if the lines are perpendicular
    if (slope1 * slope2 == -1) {
        // Lines are perpendicular
        a = x2 / slope2;
    } else {
        // Lines are not perpendicular
        a = -1;
    }

    // Print the value of a
    cout << "The value of a is: " << a << endl;

    return 0;
}

